def render_market_history_chart(history_column):
    if (
        market_risk_history.empty
        or history_column not in market_risk_history.columns
    ):
        st.caption("📈 Noch keine Verlaufshistorie vorhanden.")
        return

    chart_data = market_risk_history[
        ["Datum", history_column]
    ].copy()

    chart_data[history_column] = pd.to_numeric(
        chart_data[history_column],
        errors="coerce",
    )

    chart_data = chart_data.dropna(
        subset=["Datum", history_column]
    )

    if not chart_data.empty:
        cutoff = (
            chart_data["Datum"].max()
            - pd.DateOffset(months=12)
        )
        chart_data = chart_data[
            chart_data["Datum"] >= cutoff
        ]

    if len(chart_data) < 2:
        if not chart_data.empty:
            first_date_text = (
                chart_data["Datum"]
                .min()
                .strftime("%d.%m.%Y")
            )
            st.caption(
                "📈 Historie wird seit "
                f"{first_date_text} aufgebaut. "
                "Der Verlauf erscheint ab dem zweiten Tageswert."
            )
        else:
            st.caption("📈 Noch keine Verlaufshistorie vorhanden.")
        return

    chart_data["Datum_Label"] = (
        chart_data["Datum"].dt.strftime("%d.%m.")
    )

    chart = (
        alt.Chart(chart_data)
        .mark_bar(
            size=18,
        )
        .encode(
            x=alt.X(
                "Datum_Label:N",
                title=None,
                sort=None,
                axis=alt.Axis(
                    labelAngle=0,
                ),
            ),
            y=alt.Y(
                f"{history_column}:Q",
                title="Risiko",
                scale=alt.Scale(
                    domain=[0, 100],
                ),
                axis=alt.Axis(
                    values=[0, 25, 50, 75, 100],
                ),
            ),
            tooltip=[
                alt.Tooltip(
                    "Datum:T",
                    title="Datum",
                    format="%d.%m.%Y",
                ),
                alt.Tooltip(
                    f"{history_column}:Q",
                    title="Risiko",
                    format=".1f",
                ),
            ],
        )
        .properties(
            height=145,
            title=alt.TitleParams(
                text=item["name"],
                subtitle=[
                    item.get("subtitle", ""),
                    (
                        "1 Jahr"
                        if period_key == "1 Jahr"
                        else "Langfrist"
                    ),
                ],
                anchor="start",
                fontSize=13,
                subtitleFontSize=10,
            ),
        )
    )

    st.altair_chart(
        chart,
        use_container_width=True,
    )


